<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>Bouncing Balls in a Spinning Hexagon</title>
<style>
  body { margin:0; overflow:hidden; background:#111; }
  canvas { display:block; margin:auto; background:#222; }
</style>
</head>
<body>
<canvas id="c"></canvas>
<script>
(() => {
  const canvas = document.getElementById('c');
  const ctx = canvas.getContext('2d');
  const W = canvas.width = window.innerWidth;
  const H = canvas.height = window.innerHeight;

  const GRAVITY = 0.3;           // pixels per frame^2
  const FRICTION = 0.99;         // velocity loss on wall bounce
  const BALL_FRICTION = 0.995;   // loss on ball‑ball bounce
  const RESTITUTION = 0.9;       // bounce elasticity
  const HEX_RADIUS = Math.min(W, H) * 0.35;
  const HEX_CENTER = {x: W/2, y: H/2};
  const ANG_VEL = 0.001;         // radians per frame

  let hexAngle = 0;

  // ---------- Ball class ----------
  class Ball {
    constructor(x, y, vx, vy, r, col) {
      this.x = x; this.y = y;
      this.vx = vx; this.vy = vy;
      this.r = r;
      this.col = col;
      this.mass = r*r; // simple mass proportional to area
    }
    update() {
      this.vy += GRAVITY;
      this.x += this.vx;
      this.y += this.vy;
    }
    draw() {
      ctx.beginPath();
      ctx.arc(this.x, this.y, this.r, 0, Math.PI*2);
      ctx.fillStyle = this.col;
      ctx.fill();
    }
  }

  // ---------- Helper functions ----------
  function rand(min, max) { return Math.random()*(max-min)+min; }

  function getHexVertices(angle) {
    const verts = [];
    for (let i = 0; i < 6; i++) {
      const a = angle + i * Math.PI/3;
      verts.push({
        x: HEX_CENTER.x + HEX_RADIUS*Math.cos(a),
        y: HEX_CENTER.y + HEX_RADIUS*Math.sin(a)
      });
    }
    return verts;
  }

  function edgeNormal(p1, p2) {
    const dx = p2.x - p1.x;
    const dy = p2.y - p1.y;
    const len = Math.hypot(dx, dy);
    // outward normal (pointing away from centre)
    return {x: -dy/len, y: dx/len};
  }

  // reflect velocity v about normal n (both normalized)
  function reflect(vx, vy, nx, ny) {
    const dot = vx*nx + vy*ny;
    return {vx: vx - 2*dot*nx, vy: vy - 2*dot*ny};
  }

  // ---------- Initialize balls ----------
  const balls = [];
  const colors = ['#e74c3c','#f1c40f','#2ecc71','#3498db','#9b59b6','#e67e22','#1abc9c','#ff6b6b','#74b9ff','#fd79a8'];
  for (let i=0;i<10;i++) {
    const r = rand(15,25);
    const x = rand(HEX_CENTER.x-HEX_RADIUS+ r, HEX_CENTER.x+HEX_RADIUS- r);
    const y = rand(HEX_CENTER.y-HEX_RADIUS+ r, HEX_CENTER.y+HEX_RADIUS- r);
    const vx = rand(-2,2);
    const vy = rand(-2,2);
    balls.push(new Ball(x,y,vx,vy,r,colors[i%colors.length]));
  }

  // ---------- Collision handling ----------
  function handleBallWallCollision(ball, verts) {
    for (let i=0;i<6;i++) {
      const p1 = verts[i];
      const p2 = verts[(i+1)%6];
      const n = edgeNormal(p1,p2);
      // distance from center to infinite line
      const dist = (ball.x - p1.x)*n.x + (ball.y - p1.y)*n.y;
      if (dist < ball.r) {
        // edge velocity at contact point due to rotation
        const mid = {x:(p1.x+p2.x)/2, y:(p1.y+p2.y)/2};
        const rx = mid.x - HEX_CENTER.x;
        const ry = mid.y - HEX_CENTER.y;
        const edgeVx = -ANG_VEL * ry;
        const edgeVy =  ANG_VEL * rx;

        // relative velocity
        const relVx = ball.vx - edgeVx;
        const relVy = ball.vy - edgeVy;
        const relDotN = relVx*n.x + relVy*n.y;
        if (relDotN < 0) { // moving towards wall
          const refl = reflect(relVx, relVy, n.x, n.y);
          // apply friction & restitution
          ball.vx = (refl.vx + edgeVx) * FRICTION * RESTITUTION;
          ball.vy = (refl.vy + edgeVy) * FRICTION * RESTITUTION;
          // reposition just outside the wall
          const correction = ball.r - dist + 0.5;
          ball.x += n.x*correction;
          ball.y += n.y*correction;
        }
      }
    }
  }

  function handleBallBallCollision(b1, b2) {
    const dx = b2.x - b1.x;
    const dy = b2.y - b1.y;
    const dist = Math.hypot(dx, dy);
    const minDist = b1.r + b2.r;
    if (dist < minDist) {
      // normal
      const nx = dx / dist;
      const ny = dy / dist;
      // relative velocity
      const rvx = b2.vx - b1.vx;
      const rvy = b2.vy - b1.vy;
      const relVelAlongNormal = rvx*nx + rvy*ny;
      if (relVelAlongNormal > 0) return; // moving apart

      // impulse scalar
      const e = Math.min(RESTITUTION, RESTITUTION); // same restitution
      const j = -(1 + e) * relVelAlongNormal / (1/b1.mass + 1/b2.mass);

      const impulseX = j * nx;
      const impulseY = j * ny;

      b1.vx -= impulseX / b1.mass;
      b1.vy -= impulseY / b1.mass;
      b2.vx += impulseX / b2.mass;
      b2.vy += impulseY / b2.mass;

      // apply small friction on tangential component
      const tx = -ny, ty = nx; // tangent
      const vt1 = b1.vx*tx + b1.vy*ty;
      const vt2 = b2.vx*tx + b2.vy*ty;
      const avgT = (vt1+vt2)/2;
      b1.vx += (avgT - vt1) * (1-BALL_FRICTION);
      b1.vy += (avgT - vt1) * (1-BALL_FRICTION);
      b2.vx += (avgT - vt2) * (1-BALL_FRICTION);
      b2.vy += (avgT - vt2) * (1-BALL_FRICTION);

      // positional correction to avoid sinking
      const overlap = minDist - dist;
      const correction = overlap / (b1.mass + b2.mass);
      b1.x -= nx * correction * b2.mass;
      b1.y -= ny * correction * b2.mass;
      b2.x += nx * correction * b1.mass;
      b2.y += ny * correction * b1.mass;
    }
  }

  // ---------- Main loop ----------
  function loop() {
    ctx.clearRect(0,0,W,H);

    // update hexagon
    hexAngle += ANG_VEL;
    const verts = getHexVertices(hexAngle);

    // draw hexagon (semi‑transparent)
    ctx.beginPath();
    verts.forEach((v,i)=> {
      i===0 ? ctx.moveTo(v.x,v.y) : ctx.lineTo(v.x,v.y);
    });
    ctx.closePath();
    ctx.strokeStyle = 'rgba(255,255,255,0.3)';
    ctx.lineWidth = 4;
    ctx.stroke();

    // update and draw balls
    balls.forEach(b=> b.update());

    // collisions with walls
    balls.forEach(b => handleBallWallCollision(b, verts));

    // ball‑ball collisions (naïve O(n²) – fine for 10 balls)
    for (let i=0;i<balls.length;i++) {
      for (let j=i+1;j<balls.length;j++) {
        handleBallBallCollision(balls[i], balls[j]);
      }
    }

    // draw balls on top
    balls.forEach(b=> b.draw());

    requestAnimationFrame(loop);
  }

  requestAnimationFrame(loop);
})();
</script>
</body>
</html>
```

The script creates a canvas, continuously rotates a hexagon, updates ten balls under gravity, and resolves realistic collisions with the moving hexagon walls and each other using impulse physics.
